const playAiAlertSound = () => {
  try {
    const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
    if (!AudioContext) return;
    
    const ctx = new AudioContext();
    const mainGain = ctx.createGain();
    const filter = ctx.createBiquadFilter();
    
    filter.type = 'lowpass';
    filter.frequency.value = 520;

    mainGain.connect(filter);
    filter.connect(ctx.destination);
    mainGain.gain.value = 0.025;

    const playTone = (freq: number, startTime: number, duration: number) => {
      const osc = ctx.createOscillator();
      const env = ctx.createGain();

      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, startTime);

      env.connect(mainGain);
      env.gain.setValueAtTime(0, startTime);
      env.gain.linearRampToValueAtTime(0.8, startTime + 0.05);
      env.gain.exponentialRampToValueAtTime(0.001, startTime + duration);

      osc.start(startTime);
      osc.stop(startTime + duration);
    };

    const now = ctx.currentTime;
    // Calm ambient warm triad
    playTone(440.00, now, 0.4); // A4
    playTone(554.37, now + 0.08, 0.45); // C#5
    playTone(659.25, now + 0.16, 0.5); // E5
  } catch (e) {
    console.error("Audio playback failed", e);
  }
};

function AnimatedCounter({ value, suffix, isRtl }: { value: number, suffix: string, isRtl: boolean }) {
  const ref = useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once: true, margin: "-50px" });
  const count = useMotionValue(0);
  const rounded = useTransform(count, (latest) => Math.round(latest));

  useEffect(() => {
    if (inView) {
      const controls = animate(count, value, { duration: 2.5, ease: "easeOut" });
      return controls.stop;
    }
  }, [inView, count, value]);

  return (
    <span ref={ref} className="inline-flex items-center justify-center" dir={isRtl ? 'rtl' : 'ltr'} aria-live="polite" aria-label={`${value} ${suffix}`}>
      <motion.span>{rounded}</motion.span>
      <span>{suffix}</span>
    </span>
  );
}

